import { Shift } from '@shared/data/repository/repository.model';
import { RoleRepository } from 'app/features/access/role/repository/role-repository.service';
import { RoleProjection, RoleFilter } from 'app/features/access/role/model/role.model';
import { FormControl } from '@angular/forms';
import { input, effect, Component, signal } from '@angular/core';
import { DisplayProvider } from '@shared/data/display-provider';

@Component({
  selector: 'role-view-list',
  templateUrl: './role-view-list.component.html',
  styleUrls: ['./role-view-list.component.scss'],
  standalone: false,
})
export class RoleViewListComponent {
  filters = input<RoleFilter>();
  actionName = input<string>('role');
  fixed = input<{ [key: string]: any }>();
  hidden = input<{ [key: string]: any }>();
  search = new FormControl<any>(undefined);
  showSearchLabel = signal('Refresh');
  hideSearchLabel = signal('Refresh');
  list: Shift<RoleProjection[], RoleFilter>;
  displayer: DisplayProvider<any>;
  refreshDataLabel = signal('Refresh');
  /** Último filtro buscado, sin paginación: lo usa la exportación. */
  query = signal<RoleFilter>({});

  constructor(repository: RoleRepository) {
    this.displayer = repository.displayProvider();
    this.list = repository.projections(['resourceServer']);
    effect(() => {
      setTimeout(() => this.makeSearch());
    });
  }
  makeSearch() {
    const result = { limit: 10 } as any;
    const filter = this.search.value;
    const external = this.filters();
    if (external?.search) {
      result.search = external.search;
    }
    if (external?.name) {
      result.name = external.name;
    }
    if (external?.resourceServer) {
      result.resourceServer = external.resourceServer;
    }
    if (external?.resourceServers) {
      result.resourceServers = external.resourceServers;
    }
    if (filter?.search) {
      result.search = filter.search;
    }
    if (filter?.name) {
      result.name = filter.name;
    }
    if (filter?.resourceServer?.$ref) {
      result.resourceServer = filter.resourceServer.$ref;
    }
    if (filter?.resourceServers?.$ref) {
      result.resourceServers = filter.resourceServers.$ref;
    }
    if (filter?.order) {
      result.order = filter.order;
    }
    const { limit, ...query } = result;
    this.query.set(query);
    this.list.fetch(result);
  }

  next() {
    this.list.next();
  }

  reload() {
    this.list.reset();
  }

  prev() {
    console.log('PREV');
  }
}
